command:
$ErrorActionPreference = 'Stop'
$repoRoot = (Get-Location).Path
$targetBranch = 'issue-526-repair-critic-batching'
$expectedHead = '275f3c43633ddc11786884e494dc55f8d8334648'
$baseHead = 'ac240d76adbd153ba8cc783218db3ef32bc910c3'
$staleBranch = 'test-522-post-v54-acceptance'
$worktree = Join-Path $env:RUNNER_TEMP 'dcoir-pr527-validation'
foreach ($name in @('OPENROUTER_API_KEY','DCOIR_OPENAI_API_KEY','OPENAI_API_KEY','DCOIR_GEMINI_API','GEMINI_API_KEY','GOOGLE_API_KEY')) { Remove-Item -Path ('Env:' + $name) -ErrorAction SilentlyContinue }
git fetch origin ('refs/heads/' + $targetBranch)
if ($LASTEXITCODE -ne 0) { throw 'Failed to fetch target branch' }
$actualHead = (git rev-parse FETCH_HEAD).Trim()
if ($actualHead -ne $expectedHead) { throw ('Target head moved: expected ' + $expectedHead + ' got ' + $actualHead) }
if (Test-Path -LiteralPath $worktree) { git worktree remove --force $worktree | Out-Null }
git worktree add --detach $worktree $actualHead
if ($LASTEXITCODE -ne 0) { throw 'Failed to create exact-head worktree' }
try {
  Push-Location $worktree
  try {
    $pyFiles = @(git diff --name-only $baseHead $actualHead -- '*.py')
    if (-not $pyFiles -or $pyFiles.Count -lt 1) { throw 'No changed Python files discovered for compilation' }
    Write-Host ('Compiling changed Python files: ' + $pyFiles.Count)
    & python -m py_compile @pyFiles
    if ($LASTEXITCODE -ne 0) { throw 'Changed Python compilation failed' }
    $commands = @()
    $inside = $false
    foreach ($line in Get-Content -LiteralPath '.github/dcoir_review/openrouter-pr-review-pareto.yml') {
      if ($line -match '^validation_commands:\s*$') { $inside = $true; continue }
      if ($inside -and $line -match '^[^\s#]') { break }
      if ($inside -and $line -match '^\s*-\s+(.+)$') { $commands += $Matches[1] }
    }
    if ($commands.Count -ne 55) { throw ('Expected 55 governed validation commands, found ' + $commands.Count) }
    $bash = 'C:\Program Files\Git\bin\bash.exe'
    for ($i = 0; $i -lt $commands.Count; $i++) {
      Write-Host ('[' + ($i + 1) + '/' + $commands.Count + '] ' + $commands[$i])
      & $bash -lc $commands[$i]
      if ($LASTEXITCODE -ne 0) { throw ('Governed validation command failed at index ' + ($i + 1) + ': ' + $commands[$i]) }
    }
    git diff --exit-code
    if ($LASTEXITCODE -ne 0) { throw 'Validation mutated tracked source' }
    git diff --cached --exit-code
    if ($LASTEXITCODE -ne 0) { throw 'Validation staged tracked source changes' }
  } finally { Pop-Location }
} finally {
  git worktree remove --force $worktree | Out-Null
}
$remoteStale = git ls-remote --heads origin ('refs/heads/' + $staleBranch)
if ($LASTEXITCODE -ne 0) { throw 'Failed to inspect stale benchmark branch' }
if ($remoteStale) {
  git push origin --delete $staleBranch
  if ($LASTEXITCODE -ne 0) { throw 'Failed to delete stale benchmark branch' }
}
$remaining = git ls-remote --heads origin ('refs/heads/' + $staleBranch)
if ($LASTEXITCODE -ne 0) { throw 'Failed to read back stale branch deletion' }
if ($remaining) { throw 'Stale benchmark branch still exists after delete' }
Write-Host ('PR527_EXACT_HEAD=' + $actualHead)
Write-Host ('PYCOMPILE_COUNT=' + $pyFiles.Count)
Write-Host ('GOVERNED_VALIDATION_COMMANDS=' + $commands.Count)
Write-Host 'GOVERNED_VALIDATION_RESULT=pass'
Write-Host ('STALE_BRANCH_REMOVED=' + $staleBranch)
Write-Host 'LIVE_MODEL_INFERENCE=false'
Write-Host 'LIVE_DCOIR_REVIEW_INVOCATION=false'
Write-Host 'PR_SOURCE_MUTATION=false'
Write-Host 'READY_TRANSITION=false'
Write-Host 'MERGE_PERFORMED=false'
